#!/usr/bin/env bash
# code-help.sh
# Landing page: "How do I get a code?" opens a modal like kolskalender's
# "How to share your data from the app", with Headache Calendar screenshots:
#  - title + ✕ at the top, Close button at the bottom; Esc or a click outside also closes it
#  - step 1 "Open the app and tap Share data" with the home screen (yellow ring around Share data)
#  - step 2 "A six-digit code is shown" with the Share data screen (yellow border around the code)
#  - step 3 "Enter the code on this page and press Start …" under both
#  - the app name, "Share data" and "Start" come from each language's own texts, in bold
#  - images: public/images/code-help/code-1.webp and code-2.webp (one set for all languages);
#    a language can get its own by adding public/images/about-app/<folder>/code-1.webp / code-2.webp
#  - new texts CODE_HELP_TITLE, CODE_HELP_STEP_1/2/3 in all 35 files in src/locales/
#    (after PATIENT_CODE_HELP_TEXT, which is no longer shown)
#  - safe to run again
# Run from the project root:  bash code-help.sh
set -euo pipefail

CARD=src/components/landing/CodeCard.js
if [ ! -f "$CARD" ] || [ ! -d src/locales ]; then
  echo "✗ $CARD or src/locales not found – run this from the project root." >&2
  exit 1
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

# ---- images ------------------------------------------------------------------------------
mkdir -p public/images/code-help
cat > "$TMP/code-1.b64" <<'FILE_END'
