const fs = require("fs");
const file = process.argv[2];
let src = fs.readFileSync(file, "utf8");
if (src.includes("<CodeHelpModal")) {
  console.log(`✓ ${file} already opens the modal`);
  process.exit(0);
}
const replace = (from, to, what) => {
  if (!src.includes(from)) {
    console.error(`✗ ${file}: could not find ${what} – the file differs from what this script expects`);
    process.exit(1);
  }
  src = src.replace(from, to);
};
replace(
  'import { useLocale } from "@/components/LocaleProvider";',
  'import { useLocale } from "@/components/LocaleProvider";\nimport CodeHelpModal from "@/components/landing/CodeHelpModal";',
  "the useLocale import"
);
replace(
  "        onClick={() => setShowHelp((v) => !v)}\n        aria-expanded={showHelp}\n",
  "        onClick={() => setShowHelp(true)}\n        aria-haspopup=\"dialog\"\n",
  "the help link"
);
replace(
  `      {showHelp && (\n        <p className="mt-2 text-sm leading-relaxed text-gray-600">{t.PATIENT_CODE_HELP_TEXT}</p>\n      )}\n`,
  "      <CodeHelpModal open={showHelp} onClose={() => setShowHelp(false)} />\n",
  "the help text"
);
fs.writeFileSync(file, src);
console.log(`✓ ${file} ("How do I get a code?" opens the modal)`);
NODE_END

